// Vite build and development configuration for the sketchpad app.

// #endregion 🔖Header

// #region 🔖Configuration
// [👤compose🖱️sketchpad⚙️viteconfig🔖configuration](repo://p/u/compose/b/u/sketchpad/f/vite.config.ts/s/Configuration)
// Vite build configuration for the sketchpad application.
// Configuration MUST include MDX, React, WASM, and Tailwind CSS plugins.

import mdx from "@mdx-js/rollup";
import react from "@vitejs/plugin-react";
import path from "path";
import rehypeAutolinkHeadings from "rehype-autolink-headings";
import rehypeSlug from "rehype-slug";
import remarkFrontmatter from "remark-frontmatter";
import remarkGfm from "remark-gfm";
import remarkMdxFrontmatter from "remark-mdx-frontmatter";
import { fileURLToPath } from "url";
import { defineConfig } from "vite";
import topLevelAwait from "vite-plugin-top-level-await";
import wasm from "vite-plugin-wasm";

/**
 * Absolute file path of the current module.
// [👤compose🖱️sketchpad⚙️viteconfig🔖configuration🪨filename](repo://p/u/compose/b/u/sketchpad/f/vite.config.ts/s/Configuration/d/i/__filename)
 * Path MUST be derived from import.meta.url.
 **/
const __filename = fileURLToPath(import.meta.url);
/**
 * Absolute directory path of the current module.
// [👤compose🖱️sketchpad⚙️viteconfig🔖configuration🪨dirname](repo://p/u/compose/b/u/sketchpad/f/vite.config.ts/s/Configuration/d/i/__dirname)
 * Path MUST be derived from __filename.
 **/
const __dirname = path.dirname(__filename);

// Vite configuration with plugins, resolve aliases, and asset serving.
// Export MUST call defineConfig with the complete build configuration.
export default defineConfig(async () => {
  // normal import fails in electron due to esm stuff
  const tailwind = await import("@tailwindcss/vite");
  const fs = await import("fs");
  return {
    resolve: {
      alias: {
        "@compose/js": path.resolve(__dirname, "../js"),
        "@compose/sketchpad": path.resolve(__dirname),
        "@compose/studio": path.resolve(__dirname, "../studio"),
        "@compose/assets": path.resolve(__dirname, "../assets"),
      },
    },
    plugins: [
      tailwind.default(),
      {
        ...mdx({
          remarkPlugins: [remarkGfm, remarkFrontmatter, remarkMdxFrontmatter],
          rehypePlugins: [rehypeSlug, rehypeAutolinkHeadings],
          providerImportSource: "@mdx-js/react",
        }),
        enforce: "pre",
      },
      react(),
      wasm(),
      topLevelAwait(), // needed for older browsers to run wasm
      {
        name: "serve-wasm-and-assets",
        enforce: "pre" as const,
        configureServer(server: any) {
          const sketchpadPublicPath = path.resolve(__dirname, "public");
          const assetsPath = path.resolve(__dirname, "../assets");
          server.middlewares.use((req: any, res: any, next: any) => {
            if (req.url?.endsWith(".wasm")) {
              const wasmFile = path.join(sketchpadPublicPath, req.url);
              if (fs.existsSync(wasmFile) && fs.statSync(wasmFile).isFile()) {
                res.setHeader("Content-Type", "application/wasm");
                fs.createReadStream(wasmFile).pipe(res);
                return;
              }
            }
            if (req.url?.startsWith("/assets/")) {
              const filePath = path.join(assetsPath, req.url.replace("/assets/", ""));
              if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
                fs.createReadStream(filePath).pipe(res);
                return;
              }
            }
            next();
          });
        },
      },
    ],
    optimizeDeps: {
      include: ["golden-layout"],
      exclude: ["@compose/js", "@compose/sketchpad", "@playwright/test", "playwright", "playwright-core"],
      esbuildOptions: {
        target: "es2020",
      },
    },
    build: {
      rollupOptions: {
        external: ["@playwright/test", "node:fs/promises", "node:path", "node:url", "@compose/assets/compose/metabolism.kit.compose.json", "fs", "path", "url"],
      },
    },
    ssr: {
      noExternal: ["golden-layout"],
    },
  };
});
// #endregion 🔖Configuration
